def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def shat(s):return hashlib.sha256(s.encode()).hexdigest()
class Text(HTMLParser):
 def __init__(self):super().__init__();self.t=[]
 def handle_data(self,d):self.t.append(d)
def plain(s):
 p=Text();p.feed(s);return ' '.join(' '.join(p.t).split())
class Sections(HTMLParser):
 def __init__(self,s):super().__init__();self.s=s;self.offsets=[0];self.depth=0;self.out={};self.key=None;self.begin=0
 def pos(self):
  ln,col=self.getpos();return self.offsets[ln-1]+col
 def run(self):
  self.offsets=[0];n=0
  for line in self.s.splitlines(keepends=True):n+=len(line);self.offsets.append(n)
  self.feed(self.s);return self.out
 def handle_starttag(self,tag,attrs):
  if tag!='div':return
  a=dict(attrs)
  if self.key:self.depth+=1
  elif a.get('data-explanation') or a.get('class')=='sum':
   self.key=a.get('data-explanation','sum');self.begin=self.pos();self.depth=1
 def handle_endtag(self,tag):
  if tag=='div' and self.key:
   self.depth-=1
   if self.depth==0:
    end=self.s.index('>',self.pos())+1;self.out[self.key]=self.s[self.begin:end];self.key=None
